INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329535, 14424, 'France 24', 'en', 'West Bank: Palestinians families trapped in homes', 'https://www.france24.com/en/west-bank-palestinians-families-trapped-in-homes', 'Israeli settlers are conducting a campaign of violence and intimidation against the Palestinian village of Qusra in the occupied West Bank. Families have had their electricity and water supplies cut off, in what residents say is an attempt to force them from their homes. According to France 24 correspondent Noga Tarnopolsky, Israel’s Defence Minister is using settler violence for political propaganda, as the army could remove violent settlers but is not ordered to do so due to far-right political pressure. The situation is expected to remain unchanged, with the army standing by as armed settle', 'https://s.france24.com/media/display/2bdaae26-97cc-11f1-9696-005056bf30b7/w:1024/p:16x9/EN-20260814-120334-120852-CS.jpg', '2026-08-14T10:43:44+00:00', '2026-08-14T14:58:37.182665'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329544, 14424, 'France 24', 'en', 'Israeli settlers seize Palestinian water source in occupied West Bank to create recreational pool', 'https://www.france24.com/en/middle-east/20260814-israeli-settlers-seize-palestinian-water-source-in-occupied-west-bank-to-create-recreational-pool', 'Israeli settlers have taken control of a freshwater spring that Palestinian farmers in the occupied West Bank have relied on for generations, diverting its water to create a pool at an archaeological site advertised as a tourist attraction and leaving crops to wither. It is estimated that Israeli settlers have now seized control of 95 percent of the northern Jordan Valley''s springs, pushing Palestinian communities off their land.', 'https://s.france24.com/media/display/647b8576-97bc-11f1-bcae-005056bf30b7/w:1024/p:16x9/2026-08-14T060113Z-1927548703-RC2TVMAVHWMD-RTRMADP-3-ISRAEL-PALESTINIANS-WEST-BANK-SPRINGS.jpg', '2026-08-14T09:23:33+00:00', '2026-08-14T14:58:37.313779'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
