INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332247, 14478, 'South China Morning Post', 'en', 'US-China AI decoupling ‘manageable’ for trade – but tech curbs a ‘wild card’: Citi', 'https://www.scmp.com/economy/global-economy/article/3364073/us-china-ai-decoupling-manageable-trade-tech-curbs-wild-card-citi', 'As US-China tech tensions rise ahead of an expected leadership summit next month, analysts argue Washington’s latest restrictions are unlikely to cause a major disruption in China’s AI exports. But they caution that some of the measures – such as limiting access to “open-weight” models – represent a “genuine wild card” that could reshape the global landscape. Hong Kong-based analysts at Citi Research, led by Yu Xiangrong, argued in a Friday note that US tariffs and export controls were “unlikely...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/8cecb1f1-6c4a-4e88-ac05-e5933e622a62_f0ad5b66.jpg?itok=sPecZzsk&v=1786703256', '2026-08-14T13:00:12+00:00', '2026-08-14T15:03:28.408423'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332249, 14478, 'South China Morning Post', 'en', 'For China, Trump’s new drone tariffs threaten to deepen trade rift with US', 'https://www.scmp.com/economy/global-economy/article/3364062/china-trumps-new-drone-tariffs-threaten-deepen-trade-rift-us', 'Tariffs of up to 100 per cent that Washington has announced on imported drones would result in a “lose-lose outcome” for the United States and China, analysts said, as the technology is increasingly taking centre stage in the countries’ tech and trade rivalry. The new levies will further complicate manufacturers’ efforts to shift production to third countries or regions, where supply chains are already affected by earlier trade restrictions imposed by both sides, they added. On Thursday, US...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/a379790e-6ba8-4017-86e8-1f52a538a186_28ec14b5.jpg?itok=yH059uqe&v=1786700720', '2026-08-14T12:00:09+00:00', '2026-08-14T15:03:28.440013'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
